INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771377545696', 'Pioneer DDJ-REV1', 'The DDJ-REV1 matches perfectly with the free Serato DJ Lite software, boasting a brand-new battle-style layout that’s easy to use and perfect for playing like a pro. The design of this 2-channel DJ controller emulates a professional DJM-S mixer + PLX turntable setup, including specialized features for open-format and scratch DJs. Key Features Deck 3/4 controlSupport for Serato DJ ProClass compliantFirmware Update Manager What’s in the box DDJ-REV1 USB cable Quick start guide Precautions for use', 50000, 'DJ Controllers', 'https://pub-8ce7dd1a0bfc42fb9e3a130e1f5f5aae.r2.dev/images/products/p1771377545696_main.jpeg', 1);
