INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771377823126', 'AlphaTheta DDJ-FLX2', 'Compact 2-Channel DJ Controller Key Features: Unlocks rekordbox, Serato DJ Lite & djay Two Jog Wheels Eight Performance Pads per Deck 3-Band EQ on Each Channel Transition FX with Phrase Sync Offers Tutorials for Beginners Mac/Windows/iOS/Android Compatible Beatport Streaming, Beatsource Streaming SoundCloud Go+/DJ, and TIDAL Includes USB Cable', 40000, 'DJ Controllers', 'https://pub-8ce7dd1a0bfc42fb9e3a130e1f5f5aae.r2.dev/images/products/p1771377823126_main.jpeg', 1);
