INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771537536375', 'Oraimo watch 5N OSW-806N wireless HD calling', 'Wireless HD Calling: Bluetooth 5.3 connectivity allows for clear, direct calls from the wrist, featuring contact syncing and quick dialing. Display: 2.01-inch TFT screen, 240x296 resolution, full-touch. Battery: 300mAh lithium polymer battery. Offers 7 days of normal usage and 30 days standby. Health Tracking: 24/7 monitoring for heart rate, blood oxygen (SpO2), stress, sleep, and women''s health. Fitness: 100+ sport modes (running, cycling, dancing, etc.). Durability: IP68 waterproof and dustproof rating (resistant to water, splashes, and sweat). Dimensions: 47.8 x 39.2 x 10.95 mm. App & Compatibility: Pairs via Bluetooth 5.3 to the Oraimo Health app (Android 6.0+, iOS 12.0+). Other Features: Music control, camera remote control, alarm clock, stopwatch, timer, and calculator', 3000, 'Accessories', 'https://pub-8ce7dd1a0bfc42fb9e3a130e1f5f5aae.r2.dev/images/products/p1771537536375_main.webp', 1);
