INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771298702482', 'Pioneer DDJ-REV7 2-Channel Professional DJ Controller', 'Compatible DJ Software Serato DJ Pro DVS Control Serato DVS (Paid upgrade) Software System Requirements Visit serato.com for its specifications.  Accessories DDJ-REV7 AC adaptor Power cord USB cable Warranty (for some regions) Quick Start Guide Precautions for use Serato DJ Pro Expansion Pack Voucher (Serato Pitch ''n Time DJ) Marking Sticker Specifications Frequency Range 20 - 20000 Hz Width 732 mm Height 82.4 mm Depth 382.2 mm Weight 10.7 kg Soundcard 24 bit/48 kHz Signal-to-Noise Ratio 110 dB (USB) 95 dB (LINE) 84 dB (PHONO) Distortion < 0.003 % (USB) < 0.005 % (LINE) < 0.017 % (PHONO) Power Consumption DC 24 V, 1 000 mA Performance Control Channels 2 Deck Control 2 Trim knob Yes Jog Wheel 175 mm (Top plate) 207 mm (Platter) Color on jog display Yes Beat FX Echo Time Sweep Echo Ducking Echo Echo Out Fill Out Spiral Helix Helix Out Delay Reverb One-shot Spin One-shot Brake Duck Down Flanger Phaser HP Filter LP Filter Trans Roll Fader Synth Sine Fader Synth Saw Fader Synth Square Sound Color FX Filter Noise Pitch Dub Echo Wide Filter Sampler 8slot x 4bank Hot Cues 8 Pad Modes Hot Cue Roll Saved Loop Sampler Pitch Play Slicer Loop Saved Flip Scratch Bank Manual Loop Yes Auto Loop/Auto Beat Loop Yes Slip Mode Yes Talkover Function Yes EQ Isolator Yes Fader Crossfader Feeling Adjust Yes Crossfader Curve Adjust Yes Terminals Inputs 2 PHONO/LINE (RCA) 2 MIC (XLR & 1/4 inch TRS Jack, 1/4 inch TRS Jack) 1 AUX (RCA) Outputs 2 MASTER (XLR, RCA) 1 BOOTH (1/4 inch TRS Jack) 2 PHONES (1/4-inch stereo jack, 3.5-mm stereo mini-jack) USB 2 USB B ports', 372000, 'Accessories', 'https://pub-8ce7dd1a0bfc42fb9e3a130e1f5f5aae.r2.dev/images/products/p1771298702482_main.jpeg', 1);
