INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771563799926', 'TYPE-C 14 in 1 Hub', '14-in-1 - Get 14 connectivity options ranging from two 4K HDMI ports, a 1080p VGA port, a 5 Gbps USB-C port, a 100W USB-C PD-IN port, five USB-A ports, a 1 Gbps Ethernet port, an SD / micro SD slot, and an AUX port for all your peripheral needs. Extended View with Triple Display - Connect and stream across three monitors simultaneously in 4K via two HDMI ports and a 1080p VGA port, ideal for multitaskers. Note For macOS, the display on external monitors will be identical. Transfer Files at Super Speeds Rely on the USB-A and USB-C ports for instant transfers of your multimedia and files at impressive 5 Gbps speeds. 80W Pass-Through Charging - The hub''s 80W seamless charging solution ensures your devices receive constant power, letting you work and play without interruptions. (Note Wall charger not included) Compatibility - Supports USB-C, USB4, and Thunderbolt connections. Compatible with MacBook (macOS 12 and newer), Windows 10 and 11, ChromeOS, and laptops equipped with DP Alt Mode and Power Delivery. Note This device is not compatible with Linux. What You Get - Anker USB-C Hub (14-in-1, Triple Display), welcome guide, an 18-month warranty, and our friendly customer service.', 6500, 'Accessories', 'https://pub-8ce7dd1a0bfc42fb9e3a130e1f5f5aae.r2.dev/images/products/p1771563799926_main.png', 1);
